inline Aevrynd::Mesh3D Load(const std::filesystem::path& directory,const Recipe& p) {
    const auto path=directory/("safe-"+std::to_string(p.id)+".aemesh");
    std::ifstream file(path,std::ios::binary|std::ios::ate);
    if(!file||file.tellg()!=std::streamoff(p.bytes))throw std::runtime_error("Groundcover raw size mismatch");
    std::vector<std::byte> raw(p.bytes);file.seekg(0);
    file.read(reinterpret_cast<char*>(raw.data()),static_cast<std::streamsize>(raw.size()));
    if(!file||!FallenLogAssets::ExactHash(raw,p.sha))throw std::runtime_error("Groundcover raw SHA mismatch");
    auto loaded=Aevrynd::LoadAevryndMeshFile(path);
    if(!loaded||loaded.mesh.vertices.size()!=p.vertices||loaded.mesh.indices.size()!=std::size_t(p.triangles)*3||
        ShoulderGrove::Detail::MeshFingerprint(loaded.mesh)!=p.derivedHash)
        throw std::runtime_error("Groundcover decoded identity mismatch");
    // 已經完成貼坡與風權重作者化，不再次 Normalize。
    return std::move(loaded.mesh);
}
// 與實際 Scene 的球體可見性契約逐項核對；0 表示應可見，不能默認未觀察到就是裁切。
inline unsigned CullReason(const Expected& e,const Aevrynd::Camera3D& camera,const Aevrynd::Scene3DSubmissionOptions& options){
    using namespace Aevrynd;
    const auto b=TransformSphereBounds(e.mesh.bounds,e.pose);
    if(options.visibility.maximumDistance>0.f&&Length(b.center-camera.position)-b.radius>options.visibility.maximumDistance)return 1;
    if(options.frustumCulling&&!SphereIntersectsFrustum(b.center,b.radius,camera,1280.f/720.f))return 2;
    if(options.visibility.minimumProjectedRadiusPixels>0.f){
        const bool ortho=camera.projection.mode==ProjectionMode::Orthographic;
        const float pixels=ortho?720.f/(std::max)(.001f,camera.projection.orthographicHeight):
            360.f/std::tan(Clamp(camera.projection.verticalFieldOfView,.01f,3.13f)*.5f);
        const float depth=ortho?1.f:TransformPoint(CreateViewMatrix(camera),b.center).z;
        const float radius=ortho?b.radius*pixels:depth+b.radius<=.001f?0.f:
            depth-b.radius<=.001f?(std::numeric_limits<float>::infinity)():b.radius*pixels/depth;
        if(radius<options.visibility.minimumProjectedRadiusPixels)return 3;
    }
    return 0;
}
